// Parsea respuesta de Composio GMAIL_FETCH_EMAILS
const inputs = $input.all();
const emails = [];

for (const input of inputs) {
  const raw = input.json || {};
  // Composio response: { data: { messages: [...] }, successful: true }
  // Gmail native response: { messages: [...] } or { data: [...] }
  const msgs = raw.messages
    || raw.data?.messages
    || (Array.isArray(raw.data) ? raw.data : null)
    || [];

  for (const msg of (Array.isArray(msgs) ? msgs : [])) {
    const headers = msg.payload?.headers || msg.headers || [];
    const getHeader = (name) => {
      const h = headers.find(x => String(x.name || x.key || '').toLowerCase() === name.toLowerCase());
      return h ? (h.value || h.val || '') : '';
    };
    const from = getHeader('From');
    const to = getHeader('To');
    const subject = getHeader('Subject');
    const threadId = msg.threadId || '';
    const id = msg.id || '';
    const snippet = msg.snippet || '';

    let body = '';
    if (msg.payload?.parts) {
      const textPart = msg.payload.parts.find(p => p.mimeType === 'text/plain');
      if (textPart && textPart.body && textPart.body.data) {
        try {
          body = Buffer.from(textPart.body.data, 'base64').toString('utf-8').substring(0, 4000);
        } catch (e) { body = snippet; }
      }
    }
    if (!body) body = msg.body?.data ? Buffer.from(msg.body.data, 'base64').toString('utf-8').substring(0, 4000) : snippet;

    const emailMatch = from.match(/<([^>]+)>/);
    const fromEmail = emailMatch ? emailMatch[1] : from;

    emails.push({
      json: {
        message_id: id,
        thread_id: threadId,
        from_email: String(fromEmail).toLowerCase().trim(),
        from_name: from.replace(/<[^>]+>/, '').trim(),
        to_email: to,
        subject: subject,
        body: body,
        snippet: snippet,
        received_at: msg.internalDate ? new Date(Number(msg.internalDate)).toISOString() : new Date().toISOString(),
        is_reply: /^re:/i.test(subject),
        campaign_id: msg.campaign_id || 'agentyx'
      }
    });
  }
}

return emails.filter(e => e.json.is_reply && e.json.from_email);

// Extrae config de campaña desde Pinecone y combina con datos del email
const pinecone = $input.first().json || {};
const vectors = pinecone.vectors || {};
const campaignId = Object.keys(vectors)[0] || 'agentyx';
const vector = vectors[campaignId] || {};
const m = vector.metadata || {};

const fallbackMeta = {
  campaign_id: 'agentyx',
  product_name: 'Agentyx',
  product_desc: 'Plataforma de automatizacion inteligente con IA y agentes digitales para empresas LATAM',
  sales_email: 'fleon@levinnovation.com',
  interest_keywords: ['interesado','demo','cotizacion','reunion','precio','quiero saber mas','meeting','agenda','automatizacion']
};
const meta = Object.keys(m).length > 0 ? m : fallbackMeta;

const campaign = {
  id: meta.campaign_id || campaignId,
  campaign_id: meta.campaign_id || campaignId,
  product: {
    name: meta.product_name || 'Agentyx',
    description: meta.product_desc || ''
  },
  email: {
    from_name: meta.from_name || 'LEV Innovation',
    from_email: meta.from_email || 'prospector@levinnovation.com'
  },
  sales_team: {
    notification_emails: [meta.sales_email || 'fleon@levinnovation.com'],
    interest_keywords: Array.isArray(meta.interest_keywords) ? meta.interest_keywords : ['interesado','demo']
  }
};

// Email data del batch loop
const emailData = $('Split In Batches').item.json || {};
return [{ json: { ...emailData, campaign } }];

// Lee email + campaign del nodo anterior (Parse Campaign → Pinecone extractor)
const item = $input.first().json || {};
const email = item;
const campaign = item.campaign || {};
const product = campaign.product || {};

const inputText = [
  `EMAIL RECIBIDO DE: ${email.from_name} <${email.from_email}>`,
  `ASUNTO: ${email.subject}`,
  `CUERPO: ${email.body || email.snippet || ''}`,
  ``,
  `PRODUCTO DE CAMPANA: ${product.name || 'LEV Innovation'}`,
  `DESCRIPCION: ${product.description || ''}`,
  ``,
  `KEYWORDS DE INTERES: ${(campaign.sales_team?.interest_keywords || []).join(', ')}`,
  ``,
  `Analiza si este email muestra interes genuino en el producto.`
].join('\n');

return [{ json: { ...email, _agent_input: inputText } }];

const item = $input.first().json || {};
const raw = String(item.output || item.text || '').trim();
let parsed = {};

try {
  const match = raw.match(/{[\s\S]*}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  }
} catch (e) {
  parsed = { _parse_error: e.message };
}

const interested = Boolean(parsed.interested);
const confidence = Number(parsed.confidence || 0);

return [{ json: {
  ...item,
  interested: interested,
  confidence: confidence,
  interest_reason: parsed.reason || '',
  suggested_action: parsed.suggested_action || '',
  risk_flags: parsed.risk_flags || [],
  _parse_error: parsed._parse_error || null,
} }];

